/**
 * SYNTHETIC test images — a 64×48 drawing of two rectangles, produced locally
 * with Pillow for these tests. Not photographs, not customer data, not
 * generated by any AI service. Real, fully decodable files (unlike a bare
 * file signature), so the upload tests exercise genuine images.
 */
export const PNG_B64 =
  "";
export const JPEG_B64 =
  "";
export const WEBP_B64 =
  "";

export const PNG = Buffer.from(PNG_B64, "base64");
export const JPEG = Buffer.from(JPEG_B64, "base64");
export const WEBP = Buffer.from(WEBP_B64, "base64");
export const IMAGE_SIZE = Object.freeze({ width: 64, height: 48 });
